// Copy for the industry pages (/hvac, /plumbing, ...). One entry per trade:
// title tag, banner, summary, sections and FAQ. The page template is
// src/components/v7/industry-page.tsx and the structured data is built from the
// same entries in page-seo.tsx, so what search engines and AI assistants read is
// what the visitor sees. docs/seo-playbook.md is the standard these follow.

export type Industry = {
  slug: string;
  /** Trade name as shown on tiles and in the booking form ("Garage door"). */
  name: string;
  /** Who the page is for, plural ("garage door companies"). */
  audience: string;
  /** Title tag, without the brand suffix. */
  title: string;
  description: string;
  h1: string;
  lede: string;
  /** File stem under /public/v7/img (three widths each), its alt text, and which part of the photo the banner keeps in view (CSS object-position). */
  image: { stem: string; alt: string; focus?: string };
  summary: string;
  facts: string[];
  problemsHeading: string;
  problems: [string, string][];
  servicesHeading: string;
  /** label, heading, copy */
  services: [string, string, string][];
  searchesHeading: string;
  searchesIntro: string;
  searches: string[];
  planHeading: string;
  /** step, what happens */
  plan: [string, string][];
  /** closing heading and line */
  cta: [string, string];
  faqHeading: string;
  faq: [string, string][];
  related: string[];
};

/** Author and date shown in the byline and repeated in the structured data. */
export const INDUSTRY_AUTHOR = { name: "Brian Greenberg", role: "CEO, Rocket Llama Labs", id: "brian-greenberg" };
export const INDUSTRY_PUBLISHED = "2026-11-11";
export const INDUSTRY_UPDATED = "2026-11-11";
export const INDUSTRY_UPDATED_LABEL = "November 11, 2026";


// Two questions every trade asks. The answer names what the price depends on and what the company keeps, for that trade.
const cost = (audience: string, basis: string): [string, string] => [
  `What does marketing cost for ${audience}?`,
  `Every company is quoted on its own. For ${audience} the number depends on ${basis}. On the first call we write a marketing plan for your company with that number on it. You see the plan before you pay for anything, and you keep it either way.`,
];
const ownership = (audience: string, assets: string): [string, string] => [
  `Is there a contract, and who owns the website and ad accounts?`,
  `There is no contract. Rocket Llama Labs works month to month with ${audience}. The website, the Google Business Profile and the ad accounts are in your company's name and on your card. ${assets} are yours too. If you leave, you keep every piece and we help the next provider get set up.`,
];

